B.RC=new A.au(984314,"MaterialIcons",null,!1)
B.Sq=new A.aS(B.RC,null,B.bd,null,null)
B.aeB=new A.ag("SAFETY EMERGENCY",null,null,null,null,null,null,null,null,null,null)
B.aeV=new A.ag("This journey has been flagged for urgent safety attention. The recorded journey data remains available for authorized users.",null,null,null,null,null,null,null,null,null,null)
B.Uo=new A.kF(B.Sq,B.aeB,B.aeV,null,null,null,null,null,null,null,!0,null,null,!1,null,null,!1,null,null,null,null,null,null,null,null,!0,null,null)
